package com.example.rewards.service;
import com.example.rewards.model.Transaction; import com.example.rewards.repository.TransactionRepository; import org.junit.jupiter.api.Test; import java.math.BigDecimal; import java.time.*; import java.util.List; import static org.junit.jupiter.api.Assertions.assertEquals;
class RewardsServiceTest {private final TransactionRepository repo=()->List.of(new Transaction("T1","C001","Alice",LocalDate.of(2026,1,5),new BigDecimal("120")),new Transaction("T2","C001","Alice",LocalDate.of(2026,1,15),new BigDecimal("75")),new Transaction("T3","C001","Alice",LocalDate.of(2026,2,10),new BigDecimal("200")),new Transaction("T4","C002","Bob",LocalDate.of(2026,1,8),new BigDecimal("100"))); private final RewardsService s=new RewardsService(repo,new RewardPointsCalculator()); @Test void monthlyRewards(){var r=s.getRewardsForCustomer("C001");assertEquals(115,r.monthlyRewards().get(0).rewardPoints());assertEquals(250,r.monthlyRewards().get(1).rewardPoints());assertEquals(365,r.totalRewardPoints());} @Test void filtersCustomerAndInclusiveMonths(){var r=s.getTransactions("C001",YearMonth.of(2026,1),YearMonth.of(2026,1));assertEquals(2,r.size());} @Test void allCustomersWhenCustomerMissing(){assertEquals(3,s.getTransactions(null,YearMonth.of(2026,1),YearMonth.of(2026,1)).size());}}
